35	export async function headIndex(
36	  client: S3Client,
37	  bucket: string,
38	  slug: string,
39	): Promise<HeadIndexResult> {
40	  try {
41	    const result = await client.send(
42	      new HeadObjectCommand({ Bucket: bucket, Key: `${slug}/index.html` }),
43	    );
44	    const uploadedBy = result.Metadata?.["uploaded-by"];
45	    const uploadedAt = result.Metadata?.["uploaded-at"];
46	    return {
47	      exists: true,
48	      ...(uploadedBy !== undefined && { uploadedBy }),
49	      ...(uploadedAt !== undefined && { uploadedAt }),
50	    };
51	  } catch (err) {
52	    if (isNotFound(err)) {
53	      return { exists: false };
